 "chapterName": "বাংলা ব্যাকরণ",
 "group": "ব্যাকরণ অংশ",
 "reading": [
  {
   "h": "ব্যাকরণ ও বাংলা ব্যাকরণ",
   "ps": [
    "ব্যাকরণে ভাষার স্বরূপ ও প্রকৃতি নিয়ে আলোচনা করা হয়। ধ্বনি, শব্দ, বাক্য ইত্যাদি বিশ্লেষণের মাধ্যমে ভাষার মধ্যকার সাধারণ কিছু বৈশিষ্ট্য খুঁজে বের করা ব্যাকরণের কাজ। ব্যাকরণগ্রন্থে এসব বৈশিষ্ট্যকে সূত্রের আকারে সাজানো হয়ে থাকে। যে বিদ্যাশাখায় বাংলা ভাষার স্বরূপ ও প্রকৃতি বর্ণনা করা হয় তাকে বাংলা ব্যাকরণ বলে।",
    "প্রথম বাংলা ব্যাকরণ প্রকাশিত হয় ১৭৪৩ সালে পর্তুগিজ ভাষায়। এর লেখক ছিলেন মানোএল দা আসসুম্পসাঁউ। তাঁর বাংলা-পর্তুগিজ অভিধানের ভূমিকা অংশ হিসেবে তিনি এটি রচনা করেন। এরপর ১৭৭৮ সালে প্রকাশিত হয় নাথানিয়েল ব্রাসি হ্যালহেড প্রণীত ইংরেজি ভাষায় রচিত পূর্ণাঙ্গ একটি বাংলা ব্যাকরণ। বইটির নাম ‘এ গ্রামার অব দি বেঙ্গল ল্যাঙ্গুয়েজ’। ১৮০১ সালে উইলিয়াম কেরি এবং ১৮২৬ সালে রামমোহন রায় ইংরেজি ভাষায় আরো দুটি উল্লেখযোগ্য বাংলা ব্যাকরণ রচনা করেন। ১৮৩৩ সালে প্রকাশিত রামমোহন রায়ের ‘গৌড়ীয় ব্যাকরণ’ বাংলা ভাষায় রচিত প্রথম বাংলা ব্যাকরণ।"
   ]
  },
  {
   "h": "ব্যাকরণের আলোচ্য বিষয়",
   "ps": [
    "ভাষা হলো বাক্যের সমষ্টি। বাক্য গঠিত হয় শব্দ দিয়ে। আবার শব্দ তৈরি হয় ধ্বনি দিয়ে। এদিক থেকে ভাষার ক্ষুদ্রতম উপাদান হলো ধ্বনি। এই ধ্বনি, শব্দ, বাক্য – প্রত্যেকটি অংশই ব্যাকরণের আলোচ্য। এছাড়া শব্দের ও বাক্যের বহু ধরনের অর্থ হয়। সেসব অর্থ নিয়েও ব্যাকরণে আলোচনা করা হয়। ব্যাকরণের এসব আলোচ্য বিষয় বিভক্ত হয় অন্তত চারটি ভাগে, যথা – ধ্বনিতত্ত্ব, রূপতত্ত্ব, বাক্যতত্ত্ব ও অর্থতত্ত্ব।",
    "ধ্বনিতত্ত্বের আলোচ্য বিষয় ধ্বনি। লিখিত ভাষায় ধ্বনিকে যেহেতু বর্ণ দিয়ে প্রকাশ করা হয়, তাই বর্ণমালা সংক্রান্ত আলোচনা এর অন্তর্ভুক্ত। ধ্বনিতত্ত্বের মূল আলোচ্য বাগযন্ত্র, বাগযন্ত্রের উচ্চারণ-প্রক্রিয়া, ধ্বনির বিন্যাস, স্বর ও ব্যঞ্জনধ্বনির বৈশিষ্ট্য, ধ্বনিদল প্রভৃতি।",
    "রূপতত্ত্বে শব্দ ও তার উপাদান নিয়ে আলোচনা করা হয়। এই আলোচনায় বিশেষ্য, সর্বনাম, বিশেষণ, ক্রিয়া, ক্রিয়াবিশেষণ ইত্যাদি স্থান পায়। বিশেষ গুরুত্ব পায় শব্দগঠন প্রক্রিয়া।",
    "বাক্যতত্ত্বে বাক্য নিয়ে আলোচনা করা হয়। বাক্যের নির্মাণ এবং এর গঠন বাক্যতত্ত্বের মূল আলোচ্য। বাক্যের মধ্যে পদ ও বর্ণ কীভাবে বিন্যস্ত থাকে, বাক্যতত্ত্বে তা বর্ণনা করা হয়। এছাড়া এক ধরনের বাক্যকে অন্য ধরনের বাক্যে রূপান্তর, বাক্যের বাচ্য, উক্তি ইত্যাদি বাক্যতত্ত্বের আলোচ্য বিষয়। কারক বিশ্লেষণ, বাক্যের যোগ্যতা, বাক্যের উপাদান লোপ, যতিচিহ্ন প্রভৃতিও বাক্যতত্ত্বে আলোচিত হয়ে থাকে।"
   ]
  }
 ],
