    "অভিন্ন বা সামান্য পরিবর্তিত চেহারায় কোনো শব্দ পরপর দুইবার ব্যবহৃত হলে তাকে শব্দদ্বিত্ব বলে। শব্দদ্বিত্ব তিন ধরনের: অনুকার দ্বিত্ব, ধ্বন্যাত্মক দ্বিত্ব ও পুনরাবৃত্ত দ্বিত্ব।",
    "অনুকার দ্বিত্ব: পরপর প্রয়োগ হওয়া কাছাকাছি চেহারার শব্দকে অনুকার দ্বিত্ব বলে। এতে প্রথম শব্দটি অর্থপূর্ণ হলেও প্রায় ক্ষেত্রে দ্বিতীয় শব্দটি অর্থহীন হয় এবং প্রথম শব্দের অনুকরণে তৈরি হয়। এই অনুকরণ প্রক্রিয়ায় দ্বিতীয় শব্দের শুরুতে ট, ফ, ব, ম, শ প্রভৃতি ধ্বনি যুক্ত থাকতে দেখা যায়। তাতে শব্দকে খানিকটা অনির্দিষ্ট, সাধারণ বা গুরুত্বহীন করা হয়। প্রকাশ পায় ‘এই রকম একটা’ ভাব। যেমন – অঙ্ক-টঙ্ক, আম-টাম, কেক-টেক, ঘর-টর, গরু-টরু, ছাগল-টাগল, ঝাল-টাল, হেন-তেন, লুচিপুুচি/লুচি-ফুচি, টাট্টু-ফাট্টু, আগড়ম-বাগড়ম, চাকর-বাকর, এলোমেলো, ঝিকিমিকি, কচর-মচর, ঝিলমিল, শেষ-মেষ, অল্পসল্প, বুদ্ধিশুদ্ধি, গুটিশুটি, মোটাসোটা, নরম-সরম, ব্যাপার-স্যাপার, বুঝে-সুঝে।",
    "অনুকার দ্বিত্বে অনেক সময়ে স্বরের পরিবর্তন ঘটে, যেমন – আড়াআড়ি, খোঁজাখুঁজি, ঘোরাঘুরি, চুপচাপ, ঠোকাঠুকি, তাড়াতাড়ি, দলাদলি, দামাদামি, পাকাপাকি, বাড়াবাড়ি, মোটামুটি, টুকরো-টাকরা, ধরাধোর, জোগাড়-জাগাড়।",
    "ধ্বন্যাত্মক দ্বিত্ব: কোনো প্রাকৃতিক ধ্বনির অনুকরণে যেসব শব্দ তৈরি হয়, সেগুলোকে ধ্বন্যাত্মক শব্দ বলে। যেমন – ঠন একটি ধ্বন্যাত্মক শব্দ। কোনো ধাতব পদার্থের সঙ্গে অন্য কোনো ধাতব পদার্থের সংঘর্ষে এই ধরনের ধ্বনি তৈরি হয়। ঠন শব্দটি পরপর দুই বার বা কখনো ততোধিক বার ব্যবহৃত হলে ধ্বন্যাত্মক দ্বিত্ব সৃষ্টি হয়। যেমন – সাঁ করে তির ছুটে যায়, সাঁ সাঁ করে তিরগুলো ছুটে যাচ্ছে, সাঁ সাঁ সাঁ করে অসংখ্য তির চারদিকে ছুটে গেল। অনেক সময়ে কল্পিত ধ্বনির ভিত্তিতেও ধ্বন্যাত্মক দ্বিত্ব তৈরি হয়। যেমন – খোঁড়া টনটন করে, গা ছমছম করে। কয়েকটি ধ্বন্যাত্মক দ্বিত্বের উদাহরণ: কুট কুট, কৌত কৌত, কুটুস-কুটুস, খক খক, খুটুর-খুটুর, টুং টুং, ঠোক ঠোক, ধুপ ধুপ, দুম দুম, ঢং ঢং, চকচক, জ্বলজ্বল, ঝমঝম, টসটস, থকথকে, ফুসুর ফুসুর, ভটভট, শোঁ শোঁ, হিস হিস। কিছু ক্ষেত্রে ধ্বন্যাত্মক দ্বিত্বের মাঝখানে স্বরধ্বনির আগমন ঘটে। যেমন – খপাখপ, গবাগব, ঝটাঝট, ফটাফট, দমাদম, পটাপট।"
