    "বিশেষণের শ্রেণিবিভাগ: ১. বর্ণবাচক: যে বিশেষণ দিয়ে রং নির্দেশ করা হয়, তাকে বর্ণবাচক বিশেষণ বলে। যেমন – নীল আকাশ, সবুজ মাঠ, লাল ফিতা। ২. গুণবাচক: যে বিশেষণ দিয়ে গুণ বা বৈশিষ্ট্য বোঝায়, তাকে গুণবাচক বিশেষণ বলে। যেমন – চালাক ছেলে, ঠান্ডা পানি। ৩. অবস্থাবাচক: যে বিশেষণ দিয়ে অবস্থা বোঝায়, তাকে অবস্থাবাচক বিশেষণ বলে। যেমন – চলন্ত ট্রেন, তরল পদার্থ। ৪. ক্রমবাচক: যে বিশেষণ দিয়ে ক্রমসংখ্যা বোঝায়, তাকে ক্রমবাচক বিশেষণ বলে। যেমন – এক টাকা, আট দিন। ৫. পূরণবাচক: যে বিশেষণ দিয়ে পূরণসংখ্যা বোঝায়, তাকে পূরণবাচক বিশেষণ বলে। যেমন – তৃতীয় প্রজন্ম, ৩৪তম অনুষ্ঠান। ৬. পরিমাণবাচক: যে বিশেষণ দিয়ে পরিমাণ বা আয়তন বোঝায়, তাকে পরিমাণবাচক বিশেষণ বলে। যেমন – আধা কেজি চাল, অনেক লোক। ৭. উপাদানবাচক: যে বিশেষণ দিয়ে উপাদান নির্দেশ করে, তাকে উপাদানবাচক বিশেষণ বলে। যেমন – বেলে মাটি, পাথুরে মূর্তি। ৮. প্রশ্নবাচক: যে বিশেষণ দিয়ে প্রশ্নবাচকতা নির্দেশিত হয়, তাকে প্রশ্নবাচক বিশেষণ বলে। যেমন – কেমন গান? কতক্ষণ সময়? ৯. নির্দিষ্টতাবাচক: যে বিশেষণ দিয়ে বিশেষিত শব্দকে নির্দিষ্ট করা হয়, তাকে নির্দিষ্টতাবাচক বিশেষণ বলে। যেমন – এই দিনে, সেই সময়। ১০. ভাববাচক বিশেষণ: যেসব বিশেষণ বাক্যের অন্তর্গত অন্য বিশেষণকে বিশেষিত করে, সেসব বিশেষণকে ভাববাচক বিশেষণ বলে। যেমন – ‘খুব ভালো খবর’ ও ‘গাড়িটা বেশ জোরে চলছে’ – এসব বাক্যে ‘খুব’ এবং ‘বেশ’ ভাববাচক বিশেষণ। ১১. বিধেয় বিশেষণ: বাক্যের বিধেয় অংশে যেসব বিশেষণ বসে, সেসব বিশেষণকে বিধেয় বিশেষণ বলে। যেমন – ‘লোকটা পাগল’ বা ‘এই পুকুরের পানি ঘোলা’ – বাক্য দুটির ‘পাগল’ ও ‘ঘোলা’ বিধেয় বিশেষণ।"
