    "ক্রিয়াবিশেষণের প্রকার: ১. ধরনবাচক ক্রিয়াবিশেষণ: কোনো ক্রিয়া কীভাবে সম্পন্ন হয়, ধরনবাচক ক্রিয়াবিশেষণ তা নির্দেশ করে। যেমন – টিপ টিপ বৃষ্টি পড়ছে। ঠিকভাবে চললে কেউ কিছু বলবে না। ২. কালবাচক ক্রিয়াবিশেষণ: এই ধরনের ক্রিয়াবিশেষণ ক্রিয়া সম্পাদনের কাল নির্দেশ করে। যেমন – আজকাল ফলের চেয়ে ফুলের দাম বেশি। যথাসময়ে সে হাজির হয়। ৩. স্থানবাচক ক্রিয়াবিশেষণ: ক্রিয়ার স্থান নির্দেশ করে স্থানবাচক ক্রিয়াবিশেষণ। যেমন – মিছিলটি সামনে এগিয়ে যায়। তাকে কোথাও খুঁজে পাওয়া যাচ্ছে না। ৪. নেতিবাচক ক্রিয়াবিশেষণ: না, নি ইত্যাদি দিয়ে ক্রিয়ার নেতিবাচক অবস্থা বোঝায়। এগুলো সাধারণত ক্রিয়ার পরে বসে। যেমন – সে এখন যাবে না। তিনি বেড়াতে যাননি। এমন কথা আমার জানা নেই। ৫. পদানু ক্রিয়াবিশেষণ: বাক্যের মধ্যে বিশেষ কোনো ভূমিকা পালন না করলেও ‘কি’, ‘যে’, ‘বা’, ‘না’, ‘তো’ প্রভৃতি পদানু ক্রিয়াবিশেষণ হিসেবে কাজ করে। যেমন – কি: আমি কি যাব? যে: খুব যে বলেছিলেন আসবেন! বা: কখনো বা দেখা হবে। না: একটু ঘুরে আসুন না, ভালো লাগবে। তো: মরি তো মরব।",
    "গঠন বিবেচনায় ক্রিয়াবিশেষণকে একপদী ও বহুপদী – এই দুই ভাগে ভাগ করা যায়: একপদী ক্রিয়াবিশেষণ: আস্তে, জোরে, চেঁচিয়ে, সহজে, ভালোভাবে ইত্যাদি। বহুপদী ক্রিয়াবিশেষণ: ভয়ে ভয়ে, চুপি চুপি ইত্যাদি।"
