    "আবেগ শব্দের প্রকার: ১. সিদ্ধান্ত আবেগ: এ জাতীয় শব্দের সাহায্যে অনুমোদন, সম্মতি, সমর্থন ইত্যাদি ভাব প্রকাশ করা হয়। যেমন – হ্যাঁ, আমাদের জিততেই হবে। বেশ, তবে যাওয়াই যাক। ২. প্রশংসা আবেগ: এ ধরনের শব্দ প্রশংসা বা তারিফের মনোভাব প্রকাশে ব্যবহৃত হয়। যেমন – শাবাশ! এমন খেলাই তো চেয়েছিলাম। বাহ, চমৎকার লিখেছ। ৩. বিরক্তি আবেগ: এ ধরনের শব্দ অবজ্ঞা, ঘৃণা, বিরক্তি ইত্যাদি মনোভাব প্রকাশে ব্যবহৃত হয়। যেমন – ছি ছি! এরকম কথা তার মুখে মানায় না। জ্বালা! তোমাকে নিয়ে আর পারি না! ৪. আতঙ্ক আবেগ: এ ধরনের আবেগ-শব্দ আতঙ্ক, যন্ত্রণা, কাতরতা ইত্যাদি প্রকাশ করে। যেমন – উহু, কী বিপদে পড়া গেল। বাপরে বাপ! কী ভয়ঙ্কর ছিল রাক্ষসটা। ৫. বিস্ময় আবেগ: এ ধরনের শব্দ বিস্মিত বা আশ্চর্য হওয়ার ভাব প্রকাশ করে। যেমন – আরে! তুমি আবার কখন এলে? আহ, কী চমৎকার দৃশ্য! ৬. করুণা আবেগ: এ ধরনের শব্দ করুণা, মায়া, সহানুভূতি ইত্যাদি মনোভাব প্রকাশ করে। যেমন – আহা! বেচারার এত কষ্ট। হায় হায়! ওর এখন কী হবে!"
