    "মানপত্র: আনুষ্ঠানিকভাবে কোনো ব্যক্তি বা সমষ্টিকে বরণ করা, বিদায় দেওয়া, সংবর্ধনা ও অভিনন্দন জানানোর জন্য যে পত্র রচনা করা হয়, তাকে মানপত্র বলে। মানপত্র সাধারণত বহু দর্শক-শ্রোতার উপস্থিতিতে পাঠ করা হয়। এ ধরনের পত্রের ভাষা খানিকটা অলংকারমণ্ডিত হতে পারে। তবে এর আয়তন সংক্ষিপ্ত হওয়া বাঞ্ছনীয়। যাঁর বা যাঁদের উদ্দেশ্যে মানপত্র পড়া হয়, মানপত্রে তাঁর বা তাঁদের দক্ষতা, যোগ্যতা, কৃতিত্ব প্রভৃতির উল্লেখ করা হয়ে থাকে। মানপত্র সুন্দর হস্তাক্ষরে লিখে অথবা ছাপিয়ে বাঁধাই করা যেতে পারে। বইয়ের নমুনা: ১. এসএসসি পরীক্ষার্থীদের বিদায় উপলক্ষে মানপত্র (বিদ্যাময়ী সরকারি বালিকা উচ্চ বিদ্যালয়ের ২০২১ সালের এসএসসি পরীক্ষার্থীদের বিদায় উপলক্ষে; সম্বোধন: ‘হে বিদায়ী অগ্রজবৃন্দ’)। ২. খ্যাতিমান কবি বা সাহিত্যিকের আগমন উপলক্ষে অভিনন্দনপত্র (রাজশাহী সরকারি উচ্চ বিদ্যালয়ে নন্দিত কথাসাহিত্যিকের আগমন উপলক্ষে; সম্বোধন: ‘হে বরেণ্য অতিথি’, ‘হে নন্দিত কথাশিল্পী’, ‘হে ভবিষ্যতের দিশারি’)। সংবাদপত্রে প্রকাশের চিঠির দ্বিতীয় নমুনা: সড়ক দুর্ঘটনা প্রতিকারের দাবি জানিয়ে চিঠি—শিরোনাম ‘সড়ক দুর্ঘটনার অবসান চাই’ (লিটন রোজারিও, নীলক্ষেত, ঢাকা)। তাঁর মতে দৈনন্দিন জীবনের প্রধান সমস্যা ও আতঙ্কের নাম সড়ক দুর্ঘটনা; একটি পত্রিকার তথ্য মতে, ২০২০ সালে প্রায় সাড়ে পাঁচ হাজার সড়ক দুর্ঘটনায় সাত হাজারের বেশি মানুষ নিহত হয়েছে।",
    "আবেদনপত্র: স্কুল-কলেজে কিংবা বিভিন্ন অফিসে বা সংস্থায় প্রতিষ্ঠান-প্রধান বা দায়িত্বপ্রাপ্ত ব্যক্তিকে অনুরোধ জানিয়ে পত্র লেখার প্রয়োজন হয়। এ ধরনের পত্রকে দরখাস্ত বা আবেদনপত্র বলে। আবেদনপত্রের আকার সাধারণত সংক্ষিপ্ত হয়। সেখানে মূল প্রসঙ্গটি যথাযথভাবে উপস্থাপন করাটিই লক্ষ্য। এ ধরনের পত্রে অনেক সময়ে প্রমাণ স্বরূপ প্রয়োজনীয় কাগজপত্রের অনুলিপি সংযুক্ত করা হয়। আবেদনপত্রের কাঠামো: তারিখ, প্রাপক (পদবি ও প্রতিষ্ঠান), প্রয়োজন হলে ‘মাধ্যম’, বিষয়, সম্বোধন (মহোদয়), মূল বক্তব্য (‘বিনীত নিবেদন এই যে...’), শেষে ‘বিনীত/নিবেদক’ লিখে নাম, শ্রেণি-রোল বা স্বাক্ষর ও ঠিকানা, প্রয়োজনে সংযুক্তির তালিকা। বইয়ের নমুনা: ১. ছুটির জন্য আবেদন, ২. (অন্যান্য), ৩. সহকারী শিক্ষক পদে নিয়োগের আবেদন (ব্যক্তিগত তথ্য ও শিক্ষাগত যোগ্যতার ছকসহ)।",
